package com.civicpulse.exception; import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler {@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"error",e.getMessage()));}@ExceptionHandler(SecurityException.class) ResponseEntity<?> forbidden(SecurityException e){return ResponseEntity.status(403).body(Map.of("timestamp",Instant.now(),"error",e.getMessage()));}@ExceptionHandler(Exception.class) ResponseEntity<?> generic(Exception e){return ResponseEntity.status(500).body(Map.of("timestamp",Instant.now(),"error","Internal server error"));}}
